+#[test]
+fn rejects_effectively_equal_tdea_subkeys() -> Result<(), Unspecified> {
+    let first = [0x01, 0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef];
+    let distinct = [0x23, 0x45, 0x67, 0x89, 0xab, 0xcd, 0xef, 0x01];
+    for mask in 0..=255 {
+        let second = variant(first, mask);
+        let pair = [first, second].concat();
+        assert!(
+            EncryptingKey::cbc(UnboundCipherKey::new(&DES_EDE_FOR_LEGACY_USE_ONLY, &pair)?)
+                .is_err(),
+            "2TDEA parity mask {mask}"
+        );
+        for keys in [
+            [first, second, distinct],
+            [distinct, first, second],
+            [first, distinct, second],
+        ] {
+            let bytes = keys.concat();
+            assert!(
+                EncryptingKey::cbc(UnboundCipherKey::new(
+                    &DES_EDE3_FOR_LEGACY_USE_ONLY,
+                    &bytes
+                )?)
+                .is_err(),
+                "3TDEA parity mask {mask}"
+            );
+            assert!(
+                DecryptingKey::cbc(UnboundCipherKey::new(
+                    &DES_EDE3_FOR_LEGACY_USE_ONLY,
+                    &bytes
